export type QueryResult<T> = { rows: T[]; rowCount?: number };
export type DealRoutesClient = {
  query: <T = any>(sql: string, params?: unknown[]) => Promise<QueryResult<T>>;
  release: () => void;
};
export type DealRoutesPool = {
  query: <T = any>(sql: string, params?: unknown[]) => Promise<QueryResult<T>>;
  connect?: () => Promise<DealRoutesClient>;
};

export type DealApiMode = "phase1" | "full";

// Lightweight helpers reused across routes. These mirror the patterns used in tests (information_schema + to_regclass).
export async function hasTable(pool: DealRoutesPool, table: string): Promise<boolean> {
  try {
    const { rows } = await pool.query<{ oid: string | null }>("SELECT to_regclass($1) as oid", [table]);
    return rows?.[0]?.oid !== null;
  } catch {
    return false;
  }
}

export async function hasColumn(pool: DealRoutesPool, table: string, column: string): Promise<boolean> {
  try {
    const { rows } = await pool.query<{ ok: number }>(
      `SELECT 1 as ok FROM information_schema.columns WHERE table_name = $1 AND column_name = $2 LIMIT 1`,
      [table, column]
    );
    return Array.isArray(rows) && rows.length > 0;
  } catch {
    return false;
  }
}

export async function getColumnDataType(pool: DealRoutesPool, table: string, column: string): Promise<string | null> {
  try {
    const { rows } = await pool.query<{ data_type: string }>(
      `SELECT data_type
         FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name = $1
          AND column_name = $2
        LIMIT 1`,
      [table, column]
    );
    return rows?.[0]?.data_type ?? null;
  } catch {
    return null;
  }
}

export function isUuid(value: string): boolean {
  return z.string().uuid().safeParse(value).success;
}

export function stripEvidenceFromExecutiveSummary(exec: any): any {
  if (!exec || typeof exec !== "object") return null;
  const clone = { ...exec } as any;
  if ("evidence" in clone) delete clone.evidence;
  return clone;
}

export function stripEvidenceFromClaims(claims: any): any[] {
  if (!Array.isArray(claims)) return [];
  return claims.map((c) => {
    if (!c || typeof c !== "object") return c;
    const clone = { ...c } as any;
    if ("evidence" in clone) delete clone.evidence;
    return clone;
  });
}

export function parseDealApiMode(request: FastifyRequest | any): DealApiMode {
  const modeRaw = (request?.query as any)?.mode ?? (request as any)?.mode;
  return typeof modeRaw === "string" && modeRaw.toLowerCase() === "phase1" ? "phase1" : "full";
}

export async function bestEffortReadinessJobPresenceCheck(args: {
  pool: DealRoutesPool;
  dealId: string;
  version: string;
}): Promise<{ hasRequiredJob: boolean; blocked_reason: string | null; checked: boolean }> {
  const { pool, dealId } = args;
  const requiredTypes: JobType[] = [
    "render_document_pages",
    "extract_visuals",
    "extract_visuals_deal",
    "populate_document_page_understanding",
  ];
  const activeStatuses: JobStatus[] = ["queued", "running", "retrying"];

  let rows: Array<{ job_id: string; type: string; queue: string | null }> = [];
  try {
    const res = await pool.query(
      `SELECT job_id, type, queue
         FROM jobs
        WHERE deal_id = $1
          AND type = ANY($2::text[])
          AND status = ANY($3::text[])
          AND created_at >= (now() - interval '2 hours')
        ORDER BY created_at DESC
        LIMIT 25`,
      [dealId, requiredTypes, activeStatuses]
    );
    rows = (res as any)?.rows ?? [];
  } catch {
    // If jobs table isn't available in this context, we can't confirm.
    return { hasRequiredJob: false, blocked_reason: null, checked: false };
  }

  const hasInDb = rows.length > 0;
  if (!hasInDb) {
    try {
      const ocrRes = await pool.query(
        "SELECT 1 FROM documents WHERE deal_id = $1 AND status = 'needs_ocr' LIMIT 1",
        [dealId]
      );
      const hasNeedsOcr = Array.isArray((ocrRes as any)?.rows) && (ocrRes as any).rows.length > 0;
      if (hasNeedsOcr) {
        return { hasRequiredJob: false, blocked_reason: "INGEST_PENDING_OCR", checked: true };
      }
    } catch {
      // ignore: fall through to legacy blocked reason
    }
    // PR7-lite: If all visual-extractable docs have been finalized by extract_visuals,
    // the pipeline is complete — replace INGEST_BLOCKED_NO_JOBS with a softer reason.
    try {
      const { rows: unfinalizedRows } = await pool.query(
        `SELECT 1 FROM documents
          WHERE deal_id = $1
            AND deleted_at IS NULL
            AND NOT (extraction_metadata->'extract_visuals_finalized'->>'ok' = 'true')
            AND NOT (
                 type ILIKE '%xlsx%'
              OR type ILIKE '%xls%'
              OR (extraction_metadata->>'doc_kind') ILIKE '%excel%'
            )
          LIMIT 1`,
        [dealId]
      );
      if (unfinalizedRows.length === 0) {
        return { hasRequiredJob: false, blocked_reason: "READY_TO_ANALYZE_ENQUEUE_PENDING", checked: true };
      }
    } catch {
      // ignore: fall through to INGEST_BLOCKED_NO_JOBS
    }
    return { hasRequiredJob: false, blocked_reason: "INGEST_BLOCKED_NO_JOBS", checked: true };
  }

  // In tests, avoid requiring Redis. Treat DB presence as sufficient.
  if (process.env.NODE_ENV === "test") {
    return { hasRequiredJob: true, blocked_reason: null, checked: true };
  }

  // Best-effort: verify at least one job ID exists in BullMQ/Redis.
  try {
    const { Queue } = require("bullmq") as typeof import("bullmq");
    const qmod = require("../../lib/queue") as typeof import("../../lib/queue");
    const connection = qmod.getConnection();

    const queueCache = new Map<string, any>();
    for (const r of rows) {
      const jobId = typeof r.job_id === "string" ? r.job_id : "";
      if (!jobId) continue;
      const queueName = typeof r.queue === "string" && r.queue.trim().length > 0 ? r.queue.trim() : String(r.type || "");
      if (!queueName) continue;
      let q = queueCache.get(queueName);
      if (!q) {
        q = new Queue(queueName, { connection });
        queueCache.set(queueName, q);
      }
      const found = await q.getJob(jobId);
      if (found) return { hasRequiredJob: true, blocked_reason: null, checked: true };
    }

    try {
      const ocrRes = await pool.query(
        "SELECT 1 FROM documents WHERE deal_id = $1 AND status = 'needs_ocr' LIMIT 1",
        [dealId]
      );
      const hasNeedsOcr = Array.isArray((ocrRes as any)?.rows) && (ocrRes as any).rows.length > 0;
      if (hasNeedsOcr) {
        return { hasRequiredJob: false, blocked_reason: "INGEST_PENDING_OCR", checked: true };
      }
    } catch {
      // ignore
    }
    // PR7-lite: If all visual-extractable docs have been finalized by extract_visuals,
    // the pipeline is complete — replace INGEST_BLOCKED_NO_JOBS with a softer reason.
    try {
      const { rows: unfinalizedRows } = await pool.query(
        `SELECT 1 FROM documents
          WHERE deal_id = $1
            AND deleted_at IS NULL
            AND NOT (extraction_metadata->'extract_visuals_finalized'->>'ok' = 'true')
            AND NOT (
                 type ILIKE '%xlsx%'
              OR type ILIKE '%xls%'
              OR (extraction_metadata->>'doc_kind') ILIKE '%excel%'
            )
          LIMIT 1`,
        [dealId]
      );
      if (unfinalizedRows.length === 0) {
        return { hasRequiredJob: false, blocked_reason: "READY_TO_ANALYZE_ENQUEUE_PENDING", checked: true };
      }
    } catch {
      // ignore: fall through to INGEST_BLOCKED_NO_JOBS
    }
    return { hasRequiredJob: false, blocked_reason: "INGEST_BLOCKED_NO_JOBS", checked: true };
  } catch {
    // If Redis/BullMQ is unavailable, fall back to DB presence.
    return { hasRequiredJob: true, blocked_reason: null, checked: true };
  }
}

export function parseBoolQ(value: unknown, defaultValue = false): boolean {
  if (typeof value === "boolean") return value;
  if (typeof value === "number" && Number.isFinite(value)) return value !== 0;
  if (typeof value !== "string") return defaultValue;

  const v = value.trim().toLowerCase();
  if (!v) return defaultValue;
  if (v === "1" || v === "true" || v === "on" || v === "yes") return true;
  if (v === "0" || v === "false" || v === "off" || v === "no") return false;
  return defaultValue;
}

export function computeOcrV2CleanText(
  ocrV2: unknown,
  opts?: {
    minConfidence?: number;
    minLen?: number;
    minAlnumRatio?: number;
    maxBlocks?: number;
  }
): { text: string; keptBlocks: number; totalBlocks: number } {
  const minConfidence = typeof opts?.minConfidence === "number" && Number.isFinite(opts.minConfidence) ? opts.minConfidence : 0.55;
  const minLen = typeof opts?.minLen === "number" && Number.isFinite(opts.minLen) ? opts.minLen : 10;
  const minAlnumRatio = typeof opts?.minAlnumRatio === "number" && Number.isFinite(opts.minAlnumRatio) ? opts.minAlnumRatio : 0.4;
  const maxBlocks = typeof opts?.maxBlocks === "number" && Number.isFinite(opts.maxBlocks) ? opts.maxBlocks : 80;

  const o = ocrV2 as any;
  const blocksRaw = Array.isArray(o?.blocks) ? (o.blocks as any[]) : [];
  const totalBlocks = blocksRaw.length;

  const kept: string[] = [];
  const cleanOne = (s: string): string => s.replace(/\s+/g, " ").trim();
  const alnumRatio = (s: string): number => {
    const t = s.replace(/\s+/g, "");
    if (!t) return 0;
    const alnum = (t.match(/[A-Za-z0-9]/g) ?? []).length;
    return alnum / t.length;
  };

  for (const b of blocksRaw) {
    if (kept.length >= maxBlocks) break;
    const textRaw = typeof b?.text === "string" ? b.text : "";
    const text = cleanOne(textRaw);
    if (!text) continue;
    if (text.length < minLen) continue;
    const conf = typeof b?.confidence === "number" && Number.isFinite(b.confidence) ? b.confidence : null;
    if (conf != null && conf < minConfidence) continue;
    if (alnumRatio(text) < minAlnumRatio) continue;
    kept.push(text);
  }

  // De-dupe near-identical repeats while preserving order.
  const uniq: string[] = [];
  const seen = new Set<string>();
  for (const t of kept) {
    const key = t.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    uniq.push(t);
  }

  return {
    text: uniq.join("\n"),
    keptBlocks: uniq.length,
    totalBlocks,
  };
}

export function pickNonUnknownSegment(value: unknown): AnalystSegment | null {
  const seg = normalizeAnalystSegment(value);
  return seg && seg !== "unknown" ? seg : null;
}

export function majorityNonUnknownSegment(values: unknown[]): AnalystSegment | null {
  const counts = new Map<AnalystSegment, number>();
  const order: AnalystSegment[] = [];
  for (const v of values) {
    const seg = pickNonUnknownSegment(v);
    if (!seg) continue;
    counts.set(seg, (counts.get(seg) ?? 0) + 1);
    if (!order.includes(seg)) order.push(seg);
  }
  if (order.length === 0) return null;

  let best = order[0];
  let bestCount = -1;
  for (const seg of order) {
    const c = counts.get(seg) ?? 0;
    if (c > bestCount) {
      best = seg;
      bestCount = c;
    }
  }
  return best;
}

export function isStructuredWordSectionAsset(v: any): boolean {
  const extractorVersion = typeof v?.extractor_version === "string" ? String(v.extractor_version) : "";
  const qSource = typeof v?.quality_flags?.source === "string" ? String(v.quality_flags.source) : "";
  const kind = typeof v?.structured_json?.kind === "string" ? String(v.structured_json.kind) : "";
  if (extractorVersion === "structured_native_v1" && qSource.startsWith("structured_word")) return true;
  if (qSource.startsWith("structured_word")) return true;
  if (kind === "word_section") return true;
  return false;
}

export function structuredWordContentStats(v: any): { headingLen: number; textSnippetLen: number; paragraphsLen: number } {
  const sj = (v?.structured_json ?? {}) as any;
  const heading = typeof sj?.heading === "string" ? sj.heading.trim() : "";
  const snippet = typeof sj?.text_snippet === "string" ? sj.text_snippet.trim() : "";
  const paragraphsRaw = Array.isArray(sj?.paragraphs) ? sj.paragraphs : [];

  const paraText = (p: any): string => {
    if (typeof p === "string") return p.trim();
    if (!p || typeof p !== "object") return "";
    const direct =
      (typeof (p as any).text === "string" ? (p as any).text : "") ||
      (typeof (p as any).content === "string" ? (p as any).content : "") ||
      (typeof (p as any).value === "string" ? (p as any).value : "");
    return typeof direct === "string" ? direct.trim() : "";
  };

  let paragraphsLen = 0;
  for (const p of paragraphsRaw) {
    if (paragraphsLen >= 60) break;
    const s = paraText(p);
    if (s) paragraphsLen += 1;
  }

  return { headingLen: heading.length, textSnippetLen: snippet.length, paragraphsLen };
}

export function isEmptyStructuredWordSectionAsset(v: any): boolean {
  if (!isStructuredWordSectionAsset(v)) return false;
  const stats = structuredWordContentStats(v);
  const ocr = typeof v?.ocr_text === "string" ? v.ocr_text.replace(/\s+/g, " ").trim() : "";
  const sj = (v?.structured_json ?? {}) as any;
  const tableRows = Array.isArray(sj?.table_rows) ? sj.table_rows : [];
  let hasTable = false;
  for (const row of tableRows.slice(0, 4)) {
    if (!Array.isArray(row)) continue;
    for (const cell of row.slice(0, 6)) {
      const s = typeof cell === "string" ? cell.replace(/\s+/g, " ").trim() : cell != null ? String(cell).trim() : "";
      if (s) {
        hasTable = true;
        break;
      }
    }
    if (hasTable) break;
  }

  return stats.headingLen === 0 && stats.textSnippetLen === 0 && stats.paragraphsLen === 0 && !hasTable && !ocr;
}

export function computeDocHintSegmentByDocId(assets: any[], opts?: { minMajorityPct?: number }): Map<string, AnalystSegment> {
  const minMajorityPct = typeof opts?.minMajorityPct === "number" && Number.isFinite(opts.minMajorityPct) ? opts.minMajorityPct : 0.6;

  const nonEmptyCountByDoc = new Map<string, number>();
  const countsByDoc = new Map<string, Map<AnalystSegment, number>>();

  for (const a of assets) {
    if (!isStructuredWordSectionAsset(a)) continue;
    const docId = typeof a?.document_id === "string" ? a.document_id : typeof a?.documentId === "string" ? a.documentId : null;
    if (!docId) continue;
    if (isEmptyStructuredWordSectionAsset(a)) continue;

    nonEmptyCountByDoc.set(docId, (nonEmptyCountByDoc.get(docId) ?? 0) + 1);

    const persisted = pickNonUnknownSegment((a as any)?.persisted_segment_key);
    const computed = pickNonUnknownSegment((a as any)?.computed_segment);
    const candidate = persisted ?? computed;
    if (!candidate) continue;

    const map = countsByDoc.get(docId) ?? new Map<AnalystSegment, number>();
    map.set(candidate, (map.get(candidate) ?? 0) + 1);
    countsByDoc.set(docId, map);
  }

  const out = new Map<string, AnalystSegment>();
  for (const [docId, totalNonEmpty] of nonEmptyCountByDoc.entries()) {
    const counts = countsByDoc.get(docId);
    if (!counts || totalNonEmpty <= 0) continue;
    let bestSeg: AnalystSegment | null = null;
    let bestCount = -1;
    for (const [seg, n] of counts.entries()) {
      if (n > bestCount) {
        bestSeg = seg;
        bestCount = n;
      }
    }
    if (!bestSeg || bestSeg === "unknown" || bestCount <= 0) continue;
    const pct = bestCount / totalNonEmpty;
    if (pct >= minMajorityPct) out.set(docId, bestSeg);
  }
  return out;
}

export function applyNeighborHintPropagationToAssets(
  assets: any[],
  opts?: { maxDistancePages?: number; minNeighborConfidence?: number }
): any[] {
  const maxDistancePages =
    typeof opts?.maxDistancePages === "number" && Number.isFinite(opts.maxDistancePages) ? opts.maxDistancePages : 2;
  const minNeighborConfidence =
    typeof opts?.minNeighborConfidence === "number" && Number.isFinite(opts.minNeighborConfidence) ? opts.minNeighborConfidence : 0.65;

  const looksLikeRepeatedBrandLine = (raw: unknown): boolean => {
    if (typeof raw !== "string") return false;
    const text = raw.replace(/\s+/g, " ").trim();
    if (!text) return false;
    if (text.length > 60) return false;
    const words = text.split(" ").filter(Boolean);
    if (words.length < 2) return false;

    const normalizedWords = words.map((w) => w.replace(/[^A-Za-z0-9]/g, "")).filter(Boolean);
    if (normalizedWords.length < 2) return false;

    const first = normalizedWords[0];
    if (first.length < 3) return false;
    const allSame = normalizedWords.every((w) => w.toLowerCase() === first.toLowerCase());
    if (!allSame) return false;

    const alpha = first.replace(/[^A-Za-z]/g, "");
    const isAllCaps = alpha.length > 0 && alpha === alpha.toUpperCase();
    return isAllCaps;
  };

  const byDoc = new Map<string, any[]>();
  for (const a of assets) {
    const docId = typeof a?.document_id === "string" ? a.document_id : typeof a?.documentId === "string" ? a.documentId : null;
    if (!docId) continue;
    const list = byDoc.get(docId) ?? [];
    list.push(a);
    byDoc.set(docId, list);
  }

  const outById = new Map<string, any>();

  for (const [, list] of byDoc) {
    const sorted = list.slice().sort((a, b) => {
      const pa = typeof a?.page_index === "number" ? a.page_index : 1e9;
      const pb = typeof b?.page_index === "number" ? b.page_index : 1e9;
      if (pa !== pb) return pa - pb;
      const ca = typeof a?.created_at === "string" ? a.created_at : "";
      const cb = typeof b?.created_at === "string" ? b.created_at : "";
      if (ca !== cb) return ca.localeCompare(cb);
      return String(a?.id ?? a?.visual_asset_id ?? "").localeCompare(String(b?.id ?? b?.visual_asset_id ?? ""));
    });

    for (let i = 0; i < sorted.length; i++) {
      const v = sorted[i];
      const id = typeof v?.id === "string" ? v.id : typeof v?.visual_asset_id === "string" ? v.visual_asset_id : null;
      if (!id) continue;

      const seg = normalizeAnalystSegment(v?.segment) ?? "unknown";
      if (seg !== "unknown") {
        outById.set(id, v);
        continue;
      }

      const src = typeof v?.segment_source === "string" ? String(v.segment_source) : "";
      if (src !== "computed_v1") {
        outById.set(id, v);
        continue;
      }

      const persisted = pickNonUnknownSegment(v?.persisted_segment_key);
      if (persisted) {
        outById.set(id, v);
        continue;
      }

      const reason = typeof v?.computed_reason?.unknown_reason_code === "string" ? String(v.computed_reason.unknown_reason_code) : null;
      if (reason !== "LOW_SIGNAL") {
        outById.set(id, v);
        continue;
      }

      // Avoid propagating onto brand-only/cover-style pages (common failure mode).
      // These pages are often intentionally ignored by title extraction and should not inherit a neighbor segment.
      const evidenceCount =
        typeof v?.evidence_count === "number" && Number.isFinite(v.evidence_count)
          ? v.evidence_count
          : typeof v?.evidence_count_total === "number" && Number.isFinite(v.evidence_count_total)
            ? v.evidence_count_total
            : 0;
      const ocrText = typeof v?.ocr_text === "string" ? v.ocr_text : "";
      if (evidenceCount <= 0 && looksLikeRepeatedBrandLine(ocrText)) {
        outById.set(id, v);
        continue;
      }

      const pageIndex = typeof v?.page_index === "number" ? v.page_index : null;

      let neighbor: any | null = null;
      for (let j = i - 1; j >= 0; j--) {
        const cand = sorted[j];
        const candSeg = normalizeAnalystSegment(cand?.segment) ?? "unknown";
        if (candSeg === "unknown") continue;
        const candSrc = typeof cand?.segment_source === "string" ? String(cand.segment_source) : "";
        // Allow propagation from high-confidence first-order sources.
        // Avoid propagating from other propagated segments to prevent amplification loops.
        if (candSrc !== "computed_v1" && candSrc !== "structured_fallback_v1") continue;
        const candConf = typeof cand?.segment_confidence === "number" && Number.isFinite(cand.segment_confidence) ? cand.segment_confidence : 0;
        if (candConf < minNeighborConfidence) continue;

        const candPageIndex = typeof cand?.page_index === "number" ? cand.page_index : null;
        if (pageIndex != null && candPageIndex != null) {
          if (pageIndex - candPageIndex > maxDistancePages) break;
        } else {
          if (i - j > 1) break;
        }

        neighbor = cand;
        break;
      }

      if (!neighbor) {
        outById.set(id, v);
        continue;
      }

      const neighborSeg = normalizeAnalystSegment(neighbor?.segment) ?? "unknown";
      if (neighborSeg === "unknown") {
        outById.set(id, v);
        continue;
      }

      const neighborConf =
        typeof neighbor?.segment_confidence === "number" && Number.isFinite(neighbor.segment_confidence) ? neighbor.segment_confidence : 0.7;
      const propagatedConf = Math.max(0.55, Math.min(0.8, neighborConf * 0.9));

      outById.set(id, {
        ...v,
        segment: neighborSeg,
        effective_segment: neighborSeg,
        segment_source: "neighbor_hint_v1",
        segment_confidence: propagatedConf,
        computed_reason: {
          ...(typeof v?.computed_reason === "object" && v.computed_reason ? v.computed_reason : {}),
          rule_id: "NEIGHBOR_HINT_V1",
          neighbor_segment: neighborSeg,
          neighbor_page_index: typeof neighbor?.page_index === "number" ? neighbor.page_index : null,
          neighbor_distance_pages:
            pageIndex != null && typeof neighbor?.page_index === "number" ? Math.max(0, pageIndex - neighbor.page_index) : null,
        },
      });
    }
  }

  return assets.map((a) => {
    const id = typeof a?.id === "string" ? a.id : typeof a?.visual_asset_id === "string" ? a.visual_asset_id : null;
    return id && outById.has(id) ? outById.get(id) : a;
  });
}

export function buildDeterministicGroupCapturedText(members: any[], maxChars = 1500): string {
  const parts: string[] = [];
  const seen = new Set<string>();

  const localSnippet = (text: unknown): string => {
    if (typeof text !== "string") return "";
    const s = text.replace(/\s+/g, " ").trim();
    if (!s) return "";
    return s.length > 140 ? s.slice(0, 140) : s;
  };

  for (const m of members) {
    if (!m || typeof m !== "object") continue;

    const captured = typeof (m as any).captured_text === "string" ? String((m as any).captured_text) : "";
    const sj = (m as any).structured_json;
    const textSnippet = typeof sj?.text_snippet === "string" ? String(sj.text_snippet) : "";
    const snippet = localSnippet((m as any).ocr_text);

    const chosen = (captured || textSnippet || snippet).replace(/\s+/g, " ").trim();
    if (!chosen) continue;

    const key = chosen.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    parts.push(chosen);

    const joinedLen = parts.reduce((acc, s) => acc + s.length, 0) + Math.max(0, parts.length - 1) * 2;
    if (joinedLen >= maxChars) break;
  }

  const joined = parts.join("\n\n").trim();
  if (!joined) return "";
  if (joined.length <= maxChars) return joined;
  return `${joined.slice(0, maxChars).trimEnd()}…`;
}

export function extractStructuredWordTextForCue(v: any, maxChars = 1200): string {
  const sj = (v?.structured_json ?? {}) as any;
  const heading = typeof sj?.heading === "string" ? sj.heading.trim() : "";
  const snippet = typeof sj?.text_snippet === "string" ? sj.text_snippet.trim() : "";

  const parasRaw = Array.isArray(sj?.paragraphs) ? sj.paragraphs : [];
  const paras: string[] = [];
  for (const p of parasRaw.slice(0, 40)) {
    if (typeof p === "string") {
      const s = p.trim();
      if (s) paras.push(s);
      continue;
    }
    if (!p || typeof p !== "object") continue;
    const direct =
      (typeof (p as any).text === "string" ? (p as any).text : "") ||
      (typeof (p as any).content === "string" ? (p as any).content : "") ||
      (typeof (p as any).value === "string" ? (p as any).value : "");
    const s = typeof direct === "string" ? direct.trim() : "";
    if (s) paras.push(s);
  }

  const raw = [heading, ...paras, snippet].filter(Boolean).join("\n");
  return raw.replace(/\s+/g, " ").trim().slice(0, maxChars);
}

export function inferStructuredWordCueSegment(v: any): { segment: AnalystSegment; confidence: number; matched: string } | null {
  if (!isStructuredWordSectionAsset(v)) return null;
  if (isEmptyStructuredWordSectionAsset(v)) return null;

  const text = extractStructuredWordTextForCue(v, 1600);
  if (!text) return null;

  const t = text.toLowerCase();
  const cue = (re: RegExp, matched: string, segment: AnalystSegment, confidence: number) =>
    re.test(t) ? ({ segment, confidence, matched } as const) : null;

  // Keep this conservative and only used for computed=unknown.
  return (
    cue(/\bwhat\s+we\s+do\b/, "what we do", "overview", 0.65) ||
    cue(/\bwho\s+we\s+are\b/, "who we are", "overview", 0.6) ||
    cue(/\bkey\s+strategic\s+advantages\b/, "key strategic advantages", "overview", 0.6) ||
    cue(/\bcompany\s*:\b/, "company:", "overview", 0.55) ||
    cue(/\bbusiness\s+model\b/, "business model", "business_model", 0.65) ||
    cue(/\bhow\s+we\s+make\s+money\b/, "how we make money", "business_model", 0.65) ||
    cue(/\brevenue\s+model\b/, "revenue model", "business_model", 0.6) ||
    cue(/\bpricing\b/, "pricing", "business_model", 0.55) ||
    null
  );
}

export function requireDestructiveAuth(request: FastifyRequest | any): { ok: true } | { ok: false; status: number; error: string } {
  // Allow destructive operations in non-production by default to keep tests/dev simple.
  if (process.env.NODE_ENV !== "production") return { ok: true };

  const orgRole = (request as any)?.auth?.orgRole;
  if (typeof orgRole === "string" && orgRole.toLowerCase().includes("admin")) return { ok: true };

  const headers = (request?.headers ?? {}) as any;
  const token = headers["x-admin-token"] ?? headers["admin-token"];
  if (typeof token === "string" && token.trim() && token === process.env.ADMIN_TOKEN) return { ok: true };

  return { ok: false, status: 403, error: "Unauthorized destructive operation" };
}

